/** The finding as it is stored: a SARIF result, its fields in their stored order. */
/**
 * This finding with its detail left out for `note`: What becomes its headline, unless its What is the shorter in
 * UTF-8 bytes, `note` stands as Why here, and What to do is kept. Nothing its ID, severity, resolution or place comes
 * from changes.
 */
abridged(note: string): Finding {
	const { explanation } = this.properties;
	const what =
		Buffer.byteLength(explanation.what) < Buffer.byteLength(this.message.text)
			? explanation.what
			: this.message.text;
	return Finding.parse({
		...this.toJSON(),
		properties: { ...this.properties, explanation: { ...explanation, what, whyHere: note } },
	});
}

/**
 * The canonical bytes of `value`, by RFC 8785 (JCS), for a value whose every number is a safe integer: object keys
 * sorted by UTF-16 code units, no whitespace, and strings as `JSON.stringify` writes them. It throws a
 * {@link RecordError} for anything JCS cannot write one way: a number that is not a safe integer, a lone surrogate,
 * `undefined` anywhere, a hole, or an object that is not a plain one.
 */
export function canonicalJson(value: unknown): string {
	if (value === null || typeof value === "boolean") return JSON.stringify(value);
	if (typeof value === "number") {
		if (!Number.isSafeInteger(value)) throw invalid(`a record's numbers are safe integers, not ${value}`);
		return JSON.stringify(value);
	}
	if (typeof value === "string") {
		if (!value.isWellFormed()) throw invalid("a record's strings hold no lone surrogate");
		return JSON.stringify(value);
	}
	if (Array.isArray(value)) {
		const items: string[] = [];
		// A hole reads as undefined, which no record holds.
		for (let index = 0; index < value.length; index++) items.push(canonicalJson(value[index]));
		return `[${items.join(",")}]`;
	}
	if (typeof value === "object" && plain(value)) {
		const entries = Object.entries(value);
		entries.sort(([a], [b]) => (a < b ? -1 : 1));
		return `{${entries
			.map(([key, field]) => {
				if (!key.isWellFormed()) throw invalid("a record's keys hold no lone surrogate");
				return `${JSON.stringify(key)}:${canonicalJson(field)}`;
			})
			.join(",")}}`;

#cut(
	ordered: readonly Finding[],
	full: readonly number[],
	bare: readonly number[],
	kept: readonly number[],
	length: number,
): Map<Finding, Finding> | undefined {
	const count = ordered.length;
	const shrinks = ordered.map((_, index) => bare[index]! + length < full[index]!);
	// From each index on: how many files the findings that shrink name, the N of the note, how many shrink, and the
	// bytes of all of them without the note.
	const files: number[] = new Array(count + 1).fill(0);
	const shrinking: number[] = new Array(count + 1).fill(0);
	const abridged: number[] = new Array(count + 1).fill(0);
	const seen = new Set<string>();
	for (let index = count - 1; index >= 0; index--) {
		if (shrinks[index]) seen.add(ordered[index]!.properties.path);
		files[index] = seen.size;
		shrinking[index] = shrinking[index + 1]! + (shrinks[index] ? 1 : 0);
